// ползунок: прокрутка = перемотка
const tcRange = $('#tc-range'), tcTime = $('#tc-time'), tcCh = $('#tc-ch');
const TAPE_LEN = 92 * 60;
let dragging = false;
tcRange.addEventListener('input', () => {
  dragging = true;
  const max = document.documentElement.scrollHeight - innerHeight;
  window.scrollTo({ top: tcRange.value / 1000 * max, behavior: 'instant' });
});
tcRange.addEventListener('change', () => { dragging = false; });

const SCENE_NAMES = { hero: 'ОБЛОЖКА', who: 'ГЛ.01 КТО', pulse: 'ГЛ.02 ТОК', maze: 'ГЛ.03 ЛАБИРИНТ', tokyo: 'ГЛ.04 ТОКИО', memory: 'ГЛ.05 ПАМЯТЬ', sleep: 'ГЛ.06 СОН', spores: 'ГЛ.07 СПОРЫ', compute: 'ГЛ.08 МЫ', final: 'ГЛ.09 ФИНАЛ', calm: 'ВКЛАДЫШ' };
const sceneEls = $$('[data-scene]');
const scroll = { scene: 'hero', sceneEl: sceneEls[0], local: 0, progress: 0 };
function updateScroll() {
  const max = Math.max(1, document.documentElement.scrollHeight - innerHeight);
  scroll.progress = clamp(scrollY / max, 0, 1);
  if (!dragging) tcRange.value = Math.round(scroll.progress * 1000);
  tcTime.textContent = fmt(scroll.progress * TAPE_LEN);
  const mid = innerHeight * 0.5;
  for (const s of sceneEls) {
    const r = s.getBoundingClientRect();
    if (r.top <= mid && r.bottom > mid) {
      scroll.scene = s.dataset.scene; scroll.sceneEl = s;
      scroll.local = clamp((mid - r.top) / r.height, 0, 1);
      let label = SCENE_NAMES[scroll.scene] || '';
      if (scroll.scene === 'calm') label = 'ВКЛ. ' + (s.querySelector('.ins-letter')?.textContent || '');
      if (tcCh.textContent !== label) tcCh.textContent = label;
      break;
    }
  }
}

