const clipIO = new IntersectionObserver(es => {
  for (const e of es) if (e.isIntersecting) {
    const c = e.target;
    const R = Math.random;
    c.style.setProperty('--tx', ((R() < 0.5 ? -1 : 1) * (40 + R() * 40)).toFixed(0) + 'vw');
    c.style.setProperty('--tr', ((R() - 0.5) * 90).toFixed(0) + 'deg');
    c.classList.add('landed');
    setTimeout(() => c.classList.add('drawn'), 50);
    clipIO.unobserve(c);
  }
}, { threshold: 0.2 });
