    this.p = { SA: 0.7, SO: 9, RA: 0.6, speed: 1, deposit: 5, decay: 0.9, diff: 1, active: 1, avoid: 0, fieldW: 0, light: 0, pulse: 0, memRate: 0, memDecay: 0.999, targets: 0, arrive: 4 };
    const res = new THREE.Vector2(w, h);
