    this.dispMat = new THREE.ShaderMaterial({
      vertexShader: VERT, fragmentShader: DISP_FRAG, depthTest: false, depthWrite: false,
      uniforms: { uTrail: { value: null }, uMask: { value: this.mask }, uRes: { value: res }, uTime: { value: 0 }, uPulse: { value: 0 }, uDim: { value: 1 }, uDry: { value: 0 }, uMemShow: { value: 0 }, uGain: { value: 0.12 }, uWallStyle: { value: wallStyle } },
    });
    const ref = new Float32Array(n * n * 3);
    for (let i = 0; i < n * n; i++) { ref[i * 3] = ((i % n) + 0.5) / n; ref[i * 3 + 1] = (Math.floor(i / n) + 0.5) / n; }
