/* ================================================================
   ПАНЕЛИ-ОПЫТЫ
   ================================================================ */
const panels = [];
class Panel {
  constructor(el, sim) {
    this.el = el; this.sim = sim; this.visible = false; this.warm = !reduced; this.warmTo = 480; this.running = !reduced;
    this.svg = el.querySelector('svg');
    this.rect = null;
    el.addEventListener('pointerdown', e => {
      const r = el.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width * sim.w, y = (e.clientY - r.top) / r.height * sim.h;
      this.onPointer?.(x, y, e);
    });
    const runBtn = el.parentElement.querySelector('[data-act="run"]');
    if (runBtn && reduced) {
      runBtn.hidden = false;
      runBtn.addEventListener('click', () => { this.running = !this.running; runBtn.textContent = this.running ? '❚❚ остановить' : '▶ запустить симуляцию'; });
    }
    panels.push(this);
  }
  // reduced motion: после изменений один раз досчитать опыт «за кадром» и показать статичный результат
  rewarm() { if (reduced && !this.running) { this.warm = false; this.warmTo = this.sim.steps + 480; } }
  setAspect() { this.el.style.aspectRatio = `${this.sim.w} / ${this.sim.h}`; this.svg.setAttribute('viewBox', `0 0 ${this.sim.w} ${this.sim.h}`); this.svg.setAttribute('preserveAspectRatio', 'none'); }
  tick() {}
  measure() {
    this.rect = this.el.getBoundingClientRect();
    const v = this.rect.bottom > -120 && this.rect.top < innerHeight + 120 && this.rect.width > 0;
    if (v && !this.visible) this.onShow?.();
    this.visible = v;
  }
}

/* ---------- ЛАБИРИНТ ---------- */
function makeMaze() {
  const S = 440, C = 11, cell = S / C, n = isMobile ? 128 : 192;
  const sim = new Sim({ w: S, h: S, n, wallStyle: 0 });
  const panel = new Panel($('#maze-panel'), sim);
  panel.setAspect();
  const cv = document.createElement('canvas'); cv.width = cv.height = S;
  const g = cv.getContext('2d');
  let walls, seedN = 3, foods = [], blocked, free, showPath = true, fieldT = null;
  const clockEl = $('#maze-clock');

  function gen() {
    const R = rng(seedN++ * 7919);
    // стены: для каждой клетки — правая (0) и нижняя (1)
    walls = Array.from({ length: C * C }, () => [1, 1]);
    const seen = new Uint8Array(C * C); const st = [0]; seen[0] = 1;
    while (st.length) {
      const c = st[st.length - 1], x = c % C, y = (c / C) | 0;
      const opts = [[1, 0], [-1, 0], [0, 1], [0, -1]].filter(([dx, dy]) => { const nx = x + dx, ny = y + dy; return nx >= 0 && ny >= 0 && nx < C && ny < C && !seen[ny * C + nx]; });
      if (!opts.length) { st.pop(); continue; }
      const [dx, dy] = opts[Math.floor(R() * opts.length)];
      const nx = x + dx, ny = y + dy, nc = ny * C + nx;
      if (dx === 1) walls[c][0] = 0; else if (dx === -1) walls[nc][0] = 0; else if (dy === 1) walls[c][1] = 0; else walls[nc][1] = 0;
      seen[nc] = 1; st.push(nc);
    }
    // несколько петель — чтобы путей было больше одного, как в опыте
    for (let k = 0; k < 9; k++) {
      const x = Math.floor(R() * (C - 1)), y = Math.floor(R() * (C - 1));
      walls[y * C + x][R() < 0.5 ? 0 : 1] = 0;
    }
    g.fillStyle = '#000'; g.fillRect(0, 0, S, S);
    g.strokeStyle = '#f00'; g.lineWidth = 8; g.lineCap = 'square';
    g.strokeRect(4, 4, S - 8, S - 8);
    g.beginPath();
    for (let y = 0; y < C; y++) for (let x = 0; x < C; x++) {
      const [r, b] = walls[y * C + x];
      if (r && x < C - 1) { g.moveTo((x + 1) * cell, y * cell); g.lineTo((x + 1) * cell, (y + 1) * cell); }
      if (b && y < C - 1) { g.moveTo(x * cell, (y + 1) * cell); g.lineTo((x + 1) * cell, (y + 1) * cell); }
    }
    g.stroke();
    blocked = blockedFrom(cv);
    free = []; for (let i = 0; i < blocked.length; i++) if (!blocked[i]) free.push(i);
    const tex = maskTexture(cv);
    if (sim.mask !== BLANK) sim.mask.dispose();
    sim.setMask(tex);
    foods = [{ cx: 0, cy: 0 }, { cx: C - 1, cy: C - 1 }].map(f => ({ x: (f.cx + 0.5) * cell, y: (f.cy + 0.5) * cell }));
    reset();
  }
  function cellOf(p) { return clamp(Math.floor(p.y / cell), 0, C - 1) * C + clamp(Math.floor(p.x / cell), 0, C - 1); }
  function neighbors(c) {
    const x = c % C, y = (c / C) | 0, out = [];
    if (x < C - 1 && !walls[c][0]) out.push(c + 1);
    if (x > 0 && !walls[c - 1][0]) out.push(c - 1);
    if (y < C - 1 && !walls[c][1]) out.push(c + C);
    if (y > 0 && !walls[c - C][1]) out.push(c - C);
    return out;
  }
  function shortest() {
    const a = cellOf(foods[0]), b = cellOf(foods[1]);
    const prev = new Int32Array(C * C).fill(-2); prev[a] = -1; const q = [a];
    while (q.length) { const c = q.shift(); if (c === b) break; for (const nc of neighbors(c)) if (prev[nc] === -2) { prev[nc] = c; q.push(nc); } }
    const path = []; for (let c = b; c >= 0; c = prev[c]) path.push(c);
    return path.reverse();
  }
  function buildField() {
    const at = new Atlas(blocked, S, S, 1);
    at.tiles = foods.map(f => at.dist(f.x, f.y));
    sim.setField(at.build());
  }
  function drawOverlay() {
    const s = panel.svg; s.replaceChildren();
    if (showPath) {
      const pts = shortest().map(c => `${((c % C) + 0.5) * cell},${(((c / C) | 0) + 0.5) * cell}`);
      s.append(svgEl('polyline', { class: 'path-line', points: pts.join(' ') }));
    }
    foods.forEach((f, i) => {
      s.append(svgEl('circle', { class: 'food-dot', cx: f.x, cy: f.y, r: 7 }));
      const t = svgEl('text', { class: 'food-lbl', x: f.x + 10, y: f.y - 8 }); t.textContent = i ? 'Б' : 'А'; s.append(t);
    });
  }
  function reset() {
    sim.seedAgents(agentsFree(sim.n, free, S, S));
    sim.foods = []; sim.p.targets = 0; sim.p.active = 1;
    fieldT = null;
    drawOverlay();
    panel.rewarm();
  }
  let flip = 0;
  panel.onPointer = (x, y) => {
    if (blocked[Math.floor(y) * S + Math.floor(x)]) return;
    foods[flip] = { x, y }; flip = 1 - flip;
    if (sim.steps > 90) { buildField(); applyFoods(); }
    drawOverlay();
    panel.rewarm();
  };
  function applyFoods() { sim.foods = foods.map(f => ({ x: f.x, y: S - f.y, s: 1.2, r: 5 })); }
  panel.tick = () => {
    const st = sim.steps;
    if (st >= 90 && !fieldT) { buildField(); applyFoods(); fieldT = true; }
    const k = st < 90 ? 0 : smooth(90, 1100, st);
    sim.p.targets = st < 90 ? 0 : 1;
    sim.p.fieldW = lerp(0.2, 1.6, k); sim.p.arrive = 6;
    sim.p.active = lerp(1, 0.16, k);
    sim.p.decay = 0.9; sim.p.SO = 7; sim.p.SA = 0.6; sim.p.RA = 0.5; sim.p.deposit = 4;
    const hours = st < 90 ? 0 : Math.min(8, (st - 90) / 1010 * 8);
    const txt = st < 90 ? 'заполняет ходы' : `${hours.toFixed(1).replace('.', ',')} ч`;
    if (clockEl.textContent !== txt) clockEl.textContent = txt;
  };
  $('[data-act="maze-new"]').addEventListener('click', gen);
  $('[data-act="maze-reset"]').addEventListener('click', reset);
  const pb = $('[data-act="maze-path"]');
  pb.addEventListener('click', () => { showPath = !showPath; pb.setAttribute('aria-pressed', String(showPath)); drawOverlay(); });
  gen();
  return panel;
}

/* ---------- ТОКИО ---------- */
const KANTO = { lon0: 138.3, lat0: 34.85, lon1: 141.0, lat1: 36.95 };
const CITIES = [
  ['Токио', 139.767, 35.681], ['Иокогама', 139.638, 35.444], ['Кавасаки', 139.703, 35.531], ['Тиба', 140.123, 35.605], ['Сайтама', 139.624, 35.906],
  ['Хатиодзи', 139.339, 35.656], ['Татикава', 139.414, 35.698], ['Матида', 139.446, 35.542], ['Одавара', 139.155, 35.256], ['Хирацука', 139.349, 35.328],
  ['Фудзисава', 139.487, 35.338], ['Йокосука', 139.672, 35.281], ['Кумагая', 139.388, 36.147], ['Кавагоэ', 139.485, 35.925], ['Токородзава', 139.469, 35.799],
  ['Касукабэ', 139.753, 35.975], ['Кога', 139.709, 36.178], ['Уцуномия', 139.884, 36.559], ['Цутиура', 140.205, 36.078], ['Торидэ', 140.05, 35.911],
  ['Касива', 139.976, 35.868], ['Фунабаси', 139.983, 35.695], ['Нарита', 140.318, 35.776], ['Мобара', 140.288, 35.428], ['Кисарадзу', 139.917, 35.376],
  ['Татэяма', 139.87, 34.996], ['Омэ', 139.276, 35.788], ['Ацуги', 139.36, 35.441], ['Такасаки', 139.003, 36.322], ['Маэбаси', 139.061, 36.391],
  ['Мито', 140.472, 36.366], ['Тёси', 140.833, 35.735], ['Кофу', 138.568, 35.662], ['Ояма', 139.8, 36.314], ['Цукуба', 140.11, 36.083], ['Оцуки', 138.94, 35.61],
];
const RAIL = [
  ['Токио', 'Кавасаки', 'Иокогама', 'Фудзисава', 'Хирацука', 'Одавара'], ['Иокогама', 'Йокосука'], ['Токио', 'Татикава', 'Хатиодзи', 'Оцуки', 'Кофу'],
  ['Татикава', 'Омэ'], ['Хатиодзи', 'Матида', 'Иокогама'], ['Токио', 'Матида', 'Ацуги', 'Одавара'], ['Хирацука', 'Ацуги', 'Хатиодзи'],
  ['Токио', 'Сайтама', 'Кога', 'Ояма', 'Уцуномия'], ['Токио', 'Касукабэ'], ['Сайтама', 'Кумагая', 'Такасаки', 'Маэбаси'], ['Сайтама', 'Кавагоэ'],
  ['Токио', 'Токородзава', 'Кавагоэ'], ['Фунабаси', 'Касива', 'Сайтама', 'Токородзава', 'Татикава'], ['Токио', 'Касива', 'Торидэ', 'Цутиура', 'Мито'],
  ['Касива', 'Цукуба'], ['Токио', 'Фунабаси', 'Тиба', 'Нарита', 'Тёси'], ['Тиба', 'Кисарадзу', 'Татэяма'], ['Тиба', 'Мобара'], ['Ояма', 'Мито'], ['Ояма', 'Маэбаси'],
];
const LIGHT = [ // «засветка» — горы и озёра, как в опыте (приблизительно)
  [[138.35, 36.2], [139.0, 36.15], [139.18, 35.98], [139.2, 35.8], [139.0, 35.73], [138.7, 35.76], [138.42, 35.86]],
  [[138.95, 35.52], [139.25, 35.52], [139.3, 35.4], [139.1, 35.29], [138.95, 35.31]],
  [[138.3, 36.95], [139.9, 36.95], [139.75, 36.72], [139.3, 36.55], [138.9, 36.5], [138.3, 36.46]],
  [[140.26, 36.12], [140.45, 36.1], [140.55, 35.98], [140.4, 35.95], [140.28, 36.02]],
  [[139.86, 35.25], [140.2, 35.3], [140.25, 35.15], [140.0, 35.06], [139.86, 35.1]],
];
function projector(b, W, H) {
  return (lon, lat) => [(lon - b.lon0) / (b.lon1 - b.lon0) * W, (b.lat1 - lat) / (b.lat1 - b.lat0) * H];
}
function rleMask(R) { // холст W×H: красный — море (стена), чёрный — суша
  const cv = document.createElement('canvas'); cv.width = R.W; cv.height = R.H;
  const g = cv.getContext('2d'), im = g.createImageData(R.W, R.H), d = im.data;
  R.rle.split(';').forEach((row, y) => {
    let x = 0, land = 0;
    for (const t of row.split(',')) {
      const n = parseInt(t, 36);
      if (!land) for (let i = 0; i < n; i++) d[(y * R.W + x + i) * 4] = 255;
      x += n; land ^= 1;
    }
  });
  for (let i = 3; i < d.length; i += 4) d[i] = 255;
  g.putImageData(im, 0, 0);
  return cv;
}
function makeTokyo() {
  const W = GEO.regions.kanto.W, H = GEO.regions.kanto.H;
  const sim = new Sim({ w: W, h: H, n: isMobile ? 112 : 160, wallStyle: 1 });
  const panel = new Panel($('#tokyo-panel'), sim);
  panel.gain = 0.2;
  panel.setAspect();
  const proj = projector(KANTO, W, H);
  const cv = rleMask(GEO.regions.kanto);
  const g = cv.getContext('2d');
  const blocked = blockedFrom(cv);
  g.globalCompositeOperation = 'lighter'; g.fillStyle = '#00b400';
  for (const poly of LIGHT) { g.beginPath(); poly.forEach(([lo, la], i) => { const [x, y] = proj(lo, la); i ? g.lineTo(x, y) : g.moveTo(x, y); }); g.closePath(); g.fill(); }
  sim.setMask(maskTexture(cv));
  const pts = CITIES.map(([name, lo, la]) => { const [x, y] = proj(lo, la); return { name, x, y }; });
  // города должны быть на суше
  for (const p of pts) {
    let best = null, bd = 1e9;
    for (let dy = -6; dy <= 6; dy++) for (let dx = -6; dx <= 6; dx++) {
      const x = Math.round(p.x) + dx, y = Math.round(p.y) + dy;
      if (x >= 0 && y >= 0 && x < W && y < H && !blocked[y * W + x] && dx * dx + dy * dy < bd) { bd = dx * dx + dy * dy; best = [x, y]; }
    }
    if (best) { p.x = best[0] + 0.5; p.y = best[1] + 0.5; }
  }
  let field = null, showRail = false;
  const clockEl = $('#tokyo-clock');
  function buildField() {
    if (field) return;
    const at = new Atlas(blocked, W, H, 2);
    at.tiles = pts.map(p => at.dist(p.x, p.y));
    field = at.build();
    sim.setField(field);
  }
  function overlay() {
    const s = panel.svg; s.replaceChildren();
    const byName = Object.fromEntries(pts.map(p => [p.name, p]));
    if (showRail) for (const line of RAIL) s.append(svgEl('polyline', { class: 'rail', points: line.map(n => `${byName[n].x},${byName[n].y}`).join(' ') }));
    for (const p of pts) s.append(svgEl('circle', { class: p.name === 'Токио' ? 'city-tokyo' : 'city', cx: p.x, cy: p.y, r: p.name === 'Токио' ? 5 : 2.6 }));
    const t = svgEl('text', { class: 'food-lbl', x: pts[0].x + 8, y: pts[0].y - 6 }); t.textContent = 'Токио'; s.append(t);
  }
  function reset() {
    const ok = (x, y) => { const cx = Math.floor(x), cy = Math.floor(H - y); return cx >= 0 && cy >= 0 && cx < W && cy < H && !blocked[cy * W + cx]; };
    sim.seedAgents(agentsDisc(sim.n, pts[0].x, H - pts[0].y, 7, Math.random, ok));
    sim.foods = pts.map(p => ({ x: p.x, y: H - p.y, s: 4, r: 2.5 }));
    panel.rewarm();
  }
  panel.onShow = () => { buildField(); };
  panel.tick = () => {
    buildField();
    const st = sim.steps;
    sim.p.active = lerp(0.04, 1, smooth(0, 900, st));
    sim.p.targets = 1; sim.p.arrive = 5; sim.p.fieldW = 0.35; sim.p.diff = 0.55;
    sim.p.light = 3; sim.p.SO = 7; sim.p.SA = 0.6; sim.p.RA = 0.45; sim.p.decay = 0.88; sim.p.deposit = 3;
    const txt = `${Math.min(26, st / 1500 * 26).toFixed(0)} ч`;
    if (clockEl.textContent !== txt) clockEl.textContent = txt;
  };
  const rb = $('[data-act="tokyo-rail"]');
  rb.addEventListener('click', () => { showRail = !showRail; rb.setAttribute('aria-pressed', String(showRail)); overlay(); });
  $('[data-act="tokyo-reset"]').addEventListener('click', reset);
  reset(); overlay();
  return panel;
}

/* ---------- СВОЯ СЕТЬ ---------- */
function makeNet() {
  const el = $('#net-panel');
  const n = isMobile ? 112 : 160;
  let sim = null, panel = null, region = null, blocked = null, W = 0, H = 0, cities = [], atlas = null, showMst = false;
  const countEl = $('#net-count');
  function build(key) {
    const R = GEO.regions[key];
    if (R) {
      const [lon0, lat0, lon1, lat1] = R.b;
      W = R.W; H = R.H;
      region = { lon0, lat0, lon1, lat1, R };
    } else { W = 480; H = 340; region = null; }
    if (!sim || sim.w !== W || sim.h !== H) {
      if (sim) { sim.aRT.concat(sim.tRT).forEach(t => t.dispose()); }
      sim = new Sim({ w: W, h: H, n, wallStyle: 1 });
      if (panel) panel.sim = sim;
    }
    if (!panel) {
      panel = new Panel(el, sim);
      panel.onPointer = addCity;
      panel.tick = tick;
    }
    panel.setAspect();
    let cv;
    if (region) cv = rleMask(region.R);
    else { cv = document.createElement('canvas'); cv.width = W; cv.height = H; const g = cv.getContext('2d'); g.fillStyle = '#000'; g.fillRect(0, 0, W, H); }
    blocked = blockedFrom(cv);
    if (sim.mask !== BLANK) sim.mask.dispose();
    sim.setMask(maskTexture(cv));
    sim.setField(null);
    cities = []; atlas = new Atlas(blocked, W, H, 2);
    sim.agents = null; sim.clearTrail(); sim.foods = [];
    overlay();
  }
  function addCity(x, y) {
    if (blocked[Math.floor(y) * W + Math.floor(x)]) return;
    if (cities.length >= 20) { cities.shift(); atlas.tiles.shift(); }
    cities.push({ x, y });
    atlas.tiles.push(atlas.dist(x, y));
    if (cities.length === 1) regrow();
    rebuildField();
    overlay();
    panel.rewarm();
  }
  function rebuildField() {
    sim.setField(cities.length ? atlas.build() : null);
    sim.foods = cities.map(c => ({ x: c.x, y: H - c.y, s: 4, r: 2.5 }));
  }
  function regrow() {
    if (!cities.length) return;
    const c = cities[0];
    const ok = (x, yy) => { const cx = Math.floor(x), cy = Math.floor(H - yy); return cx >= 0 && cy >= 0 && cx < W && cy < H && !blocked[cy * W + cx]; };
    sim.seedAgents(agentsDisc(n, c.x, H - c.y, 7, Math.random, ok));
  }
  function mst() {
    const k = cities.length; if (k < 2) return [];
    const inT = new Uint8Array(k), best = new Float32Array(k).fill(1e9), par = new Int32Array(k).fill(-1); best[0] = 0; const edges = [];
    for (let it = 0; it < k; it++) {
      let u = -1; for (let i = 0; i < k; i++) if (!inT[i] && (u < 0 || best[i] < best[u])) u = i;
      inT[u] = 1; if (par[u] >= 0) edges.push([par[u], u]);
      for (let v = 0; v < k; v++) if (!inT[v]) { const d = Math.hypot(cities[u].x - cities[v].x, cities[u].y - cities[v].y); if (d < best[v]) { best[v] = d; par[v] = u; } }
    }
    return edges;
  }
  function overlay() {
    const s = panel.svg; s.replaceChildren();
    if (region) {
      const proj = projector(region, W, H);
      for (const line of region.R.borders) {
        const pts = []; for (let i = 0; i < line.length; i += 2) pts.push(proj(line[i] + region.lon0, line[i + 1] + region.lat0).join(','));
        s.append(svgEl('polyline', { points: pts.join(' '), fill: 'none', stroke: 'rgba(232,198,78,.35)', 'stroke-width': 1, 'stroke-dasharray': '3 3' }));
      }
    }
    if (showMst) for (const [a, b] of mst()) s.append(svgEl('line', { class: 'mst', x1: cities[a].x, y1: cities[a].y, x2: cities[b].x, y2: cities[b].y }));
    cities.forEach((c, i) => {
      s.append(svgEl('circle', { class: i ? 'city' : 'city-tokyo', cx: c.x, cy: c.y, r: i ? 3.5 : 5 }));
      const t = svgEl('text', { class: 'food-lbl', x: c.x + 7, y: c.y - 6 }); t.textContent = String(i + 1); s.append(t);
    });
    countEl.textContent = `городов: ${cities.length}`;
  }
  function tick() {
    if (!sim.agents) return;
    const st = sim.steps;
    sim.p.active = lerp(0.04, 1, smooth(0, 800, st));
    sim.p.targets = cities.length > 1 ? 1 : 0; sim.p.arrive = 5; sim.p.fieldW = 0.35; sim.p.diff = 0.55;
    sim.p.SO = 7; sim.p.SA = 0.6; sim.p.RA = 0.45; sim.p.decay = 0.88; sim.p.deposit = 3;
  }
  $('#region').addEventListener('change', e => build(e.target.value));
  $('[data-act="net-clear"]').addEventListener('click', () => { cities = []; atlas.tiles = []; sim.agents = null; sim.clearTrail(); sim.foods = []; sim.setField(null); overlay(); });
  $('[data-act="net-regrow"]').addEventListener('click', regrow);
  const mb = $('[data-act="net-mst"]');
  mb.addEventListener('click', () => { showMst = !showMst; mb.setAttribute('aria-pressed', String(showMst)); overlay(); });
  build($('#region').value);
  return panel;
}

/* ================================================================
   ФОН: главная сеть + сцены глав
   ================================================================ */
const SCENES = {
  hero: { pulse: 0, avoid: 0, mem: 0, dim: 1 },
  who: { pulse: 0, avoid: 0, mem: 0, dim: 1 },
  pulse: { pulse: 1, avoid: 0, mem: 0, dim: 1 },
  maze: { pulse: 0, avoid: 0, mem: 0, dim: 0.55 },
  tokyo: { pulse: 0, avoid: 0, mem: 0, dim: 0.55 },
  memory: { pulse: 0, avoid: 1, mem: 1, dim: 1 },
  sleep: { pulse: 0, avoid: 0, mem: 0, dim: 1 },
  spores: { pulse: 0, avoid: 0, mem: 0, dim: 1 },
  compute: { pulse: 0, avoid: 0, mem: 0, dim: 1 },
  final: { pulse: 0, avoid: 0, mem: 0, dim: 1.08 },
  calm: { pulse: 0, avoid: 0, mem: 0, dim: 0.6 },
};
const cur = { pulse: 0, avoid: 0, mem: 0, dim: 1, dry: 0, active: 0.1 };
let bg = null, screenRT = null, postMat = null;
const pointer = { x: -1, y: -1, until: 0, over: false };
let quality = { dpr: Math.min(isMobile ? 1 : 1.5, devicePixelRatio || 1), bgSteps: isMobile ? 1 : 2, cap: 1 };

function makeBg() {
  const cw = canvas.clientWidth || innerWidth, ch = canvas.clientHeight || innerHeight;
  const w = Math.round(isMobile ? Math.min(360, cw / 1.1) : Math.min(900, cw / 1.6));
  const h = Math.max(120, Math.round(w * ch / cw));
  const n = isMobile ? 144 : 320;
  if (bg) { bg.aRT.concat(bg.tRT).forEach(t => t.dispose()); }
  bg = new Sim({ w, h, n, wrap: true });
  bg.seedAgents(agentsDisc(n, w * 0.5, h * 0.52, Math.min(w, h) * 0.06));
  bg.p.memDecay = 0.9985;
  bg.bw = cw;
}
function resize() {
  if (!renderer) return;
  const cw = canvas.clientWidth || innerWidth, ch = canvas.clientHeight || innerHeight;
  renderer.setPixelRatio(quality.dpr);
  renderer.setSize(cw, ch, false);
  const W = Math.round(cw * quality.dpr), H = Math.round(ch * quality.dpr);
  if (!screenRT) screenRT = new THREE.WebGLRenderTarget(W, H, { depthBuffer: false, stencilBuffer: false, minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter });
  else screenRT.setSize(W, H);
  postMat.uniforms.uRes.value.set(W, H);
  if (!bg || Math.abs(bg.bw - cw) / cw > 0.2) makeBg();
}

function setupPointer() {
  const toBg = (cx, cy) => {
    const r = canvas.getBoundingClientRect();
    return [(cx - r.left) / r.width * bg.w, (1 - (cy - r.top) / r.height) * bg.h];
  };
  addEventListener('pointermove', e => {
    if (!bg) return;
    const inPanel = e.target.closest?.('.simpanel');
    pointer.over = !inPanel;
    [pointer.x, pointer.y] = toBg(e.clientX, e.clientY);
    pointer.until = performance.now() + (e.pointerType === 'mouse' ? 1500 : 4000);
  }, { passive: true });
  addEventListener('pointerdown', e => {
    if (!bg || e.target.closest?.('.simpanel, button, a, input, select')) return;
    [pointer.x, pointer.y] = toBg(e.clientX, e.clientY);
    pointer.over = true; pointer.until = performance.now() + 4000;
  }, { passive: true });
}

/* ================================================================
   ЦИКЛ
   ================================================================ */
const fps = { acc: 0, n: 0, value: 0, last: performance.now(), slow: 0, samples: [] };
const fpsOut = $('#fps-out');
let warmBg = reduced;

function frame(now) {
  requestAnimationFrame(frame);
  const dt = Math.min(0.1, (now - fps.last) / 1000); fps.last = now;
  fps.acc += dt; fps.n++;
  if (fps.acc >= 1) {
    fps.value = fps.n / fps.acc; fps.samples.push(fps.value); if (fps.samples.length > 30) fps.samples.shift();
    fps.acc = 0; fps.n = 0;
    fpsOut.textContent = `FPS: ${fps.value.toFixed(0)} · агентов на фоне: ${(bg ? bg.n * bg.n : 0).toLocaleString('ru-RU')}`;
    // адаптивное качество
    if (!paused && !reduced && fps.value < 28) { if (++fps.slow >= 3) { fps.slow = 0; degrade(); } } else fps.slow = 0;
  }
  updateScroll();
  updateChaos();
  if (!renderer) return;
  const t = now / 1000;
  const motionOn = !paused && !reduced;
  state.motion = lerp(state.motion, motionOn ? 1 : 0, 0.1);
  state.mode = lerp(state.mode, state.modeTarget, 0.08);

  // сцена главы → параметры фона
  const sc = SCENES[scroll.scene] || SCENES.hero;
  const k = 0.05;
  cur.pulse = lerp(cur.pulse, sc.pulse, k); cur.avoid = lerp(cur.avoid, sc.avoid, k); cur.mem = lerp(cur.mem, sc.mem, k); cur.dim = lerp(cur.dim, sc.dim, k);
  let dryT = 0;
  if (scroll.scene === 'sleep') { const s = scroll.local; dryT = s < 0.55 ? smooth(0.08, 0.4, s) : 1 - smooth(0.6, 0.88, s); }
  cur.dry = lerp(cur.dry, dryT, 0.06);
  const growth = clamp(0.08 + scrollY / (innerHeight * 2.5), 0.08, 1);
  cur.active = lerp(cur.active, growth * (1 - cur.dry * 0.96), 0.05);

  const P = bg.p;
  P.active = (warmBg ? 1 : cur.active) * quality.cap; P.avoid = cur.avoid * 1.2; P.memRate = 0.004 + cur.mem * 0.01; P.pulse = cur.pulse;
  P.decay = lerp(0.9, 0.8, cur.dry); P.speed = lerp(1, 0.35, cur.dry);
  bg.attr = (pointer.over && now < pointer.until) ? [{ x: pointer.x, y: pointer.y, s: 6, r: 40 }] : [];
  bg.foods = bg.attr.length ? [{ x: pointer.x, y: pointer.y, s: 1.5, r: 3 }] : [];

  if (warmBg) { // reduced motion: один раз «вырастить» сеть и заморозить
    bg.step(8);
    if (bg.steps > 500) warmBg = false;
  } else if (motionOn) bg.step(quality.bgSteps);

  for (const p of panels) {
    p.measure();
    if (!p.visible) continue;
    p.tick();
    if (!p.warm) { p.sim.step(12); if (p.sim.steps >= p.warmTo || !p.sim.agents) p.warm = true; }
    else if ((motionOn || (reduced && p.running && !paused))) p.sim.step(isMobile ? 1 : 2);
  }

  // композиция
  bg.display(screenRT, t * state.motion, { pulse: cur.pulse * state.motion + cur.pulse * 0.0, dim: cur.dim, dry: cur.dry, mem: cur.mem, gain: 0.22 });
  const cr = canvas.getBoundingClientRect();
  const dpr = quality.dpr;
  for (const p of panels) {
    if (!p.visible || !p.warm) continue;
    const r = p.rect;
    if (r.bottom < cr.top || r.top > cr.bottom) continue;
    const x = Math.round((r.left - cr.left) * dpr), y = Math.round((cr.bottom - r.bottom) * dpr);
    const w = Math.round(r.width * dpr), h = Math.round(r.height * dpr);
    screenRT.viewport.set(x, y, w, h); screenRT.scissor.set(x, y, w, h); screenRT.scissorTest = true;
    renderer.setRenderTarget(screenRT); // применить вьюпорт
    p.sim.display(screenRT, t * state.motion, { gain: p.gain || 0.3 });
    screenRT.viewport.set(0, 0, screenRT.width, screenRT.height); screenRT.scissorTest = false;
  }
  const pu = postMat.uniforms;
  pu.uTex.value = screenRT.texture; pu.uTime.value = t; pu.uMotion.value = state.motion; pu.uMode.value = state.mode;
  pass(postMat, null);
}
function degrade() {
  if (quality.dpr > 1) { quality.dpr = 1; resize(); return; }
  if (quality.bgSteps > 1) { quality.bgSteps = 1; return; }
  if (quality.cap > 0.3) quality.cap *= 0.6;
}

/* ================================================================
   СТАРТ
   ================================================================ */
function start() {
  drawWorld();
  document.fonts?.ready.then(drawWorld);
  addEventListener('resize', () => { drawWorld(); resize(); });
  mqReduced.addEventListener?.('change', e => { reduced = e.matches; document.body.classList.toggle('reduced', reduced); });
  if (!renderer) { requestAnimationFrame(function loop() { requestAnimationFrame(loop); updateScroll(); updateChaos(); }); return; }
  quadScene = new THREE.Scene(); quadCam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2)); quad.frustumCulled = false; quadScene.add(quad);
  postMat = new THREE.ShaderMaterial({ vertexShader: VERT, fragmentShader: POST_FRAG, depthTest: false, depthWrite: false,
    uniforms: { uTex: { value: null }, uRes: { value: new THREE.Vector2(1, 1) }, uTime: { value: 0 }, uMotion: { value: 1 }, uMode: { value: 0 } } });
  resize();
  setupPointer();
  makeMaze(); makeTokyo(); makeNet();
  requestAnimationFrame(frame);
  window.__blob = { fps, quality, bg: () => bg, panels, scroll, cur, THREE, renderer, pass, screenRT: () => screenRT,
    // для автотестов: прокрутить симуляции вперёд
    ff(n) { for (let i = 0; i < n; i += 10) { bg.step(10); for (const p of panels) if (p.visible) { p.tick(); p.sim.step(10); } } } };
}
start();
